/// Keyboard-page USB HID positions translated to the macOS virtual key codes in HIToolbox/Events.h.
/// These positions do not depend on the character the local input source produced.
enum MacKeyboardPosition {
    private static let letters: [UInt16] = [
        0x00, 0x0B, 0x08, 0x02, 0x0E, 0x03, 0x05, 0x04, 0x22,  // A–I
        0x26, 0x28, 0x25, 0x2E, 0x2D, 0x1F, 0x23, 0x0C, 0x0F,  // J–R
        0x01, 0x11, 0x20, 0x09, 0x0D, 0x07, 0x10, 0x06         // S–Z
    ]
    private static let digits: [UInt16] = [0x12, 0x13, 0x14, 0x15, 0x17, 0x16, 0x1A, 0x1C, 0x19, 0x1D] // 1–9, 0
    private static let functions: [UInt16] = [
        0x7A, 0x78, 0x63, 0x76, 0x60, 0x61, 0x62, 0x64, 0x65, 0x6D, 0x67, 0x6F, // F1–F12
        0x69, 0x6B, 0x71, 0x6A, 0x40, 0x4F, 0x50, 0x5A                         // F13–F20
    ]
    private static let keypadDigits: [UInt16] = [0x53, 0x54, 0x55, 0x56, 0x57, 0x58, 0x59, 0x5B, 0x5C, 0x52]
    private static let modifiers: [UInt16] = [0x3B, 0x38, 0x3A, 0x37, 0x3E, 0x3C, 0x3D, 0x36]

    static func isCharacterKey(_ usage: UInt32) -> Bool {
        switch usage {
        case 0x04...0x27, 0x2C...0x38, 0x54...0x57, 0x59...0x64, 0x67, 0x85, 0x87, 0x89:
            true
        default:
            false
        }
    }

    static func keyCode(for usage: UInt32) -> UInt16? {
        switch usage {
        case 0x04...0x1D: letters[Int(usage - 0x04)]
        case 0x1E...0x27: digits[Int(usage - 0x1E)]
        case 0x28: 0x24 // Return
        case 0x29: 0x35 // Escape
        case 0x2A: 0x33 // Backspace
        case 0x2B: 0x30 // Tab
        case 0x2C: 0x31 // Space
        case 0x2D: 0x1B // Minus
        case 0x2E: 0x18 // Equal
        case 0x2F: 0x21 // Left bracket
        case 0x30: 0x1E // Right bracket
        case 0x31, 0x32: 0x2A // Backslash position on ANSI and ISO keyboards
        case 0x33: 0x29 // Semicolon
        case 0x34: 0x27 // Quote
        case 0x35: 0x32 // Grave
        case 0x36: 0x2B // Comma
        case 0x37: 0x2F // Period
        case 0x38: 0x2C // Slash
        case 0x39: 0x39 // Caps Lock
        case 0x3A...0x45: functions[Int(usage - 0x3A)]
        case 0x49: 0x72 // Insert / Help
        case 0x4A: 0x73 // Home
        case 0x4B: 0x74 // Page Up
        case 0x4C: 0x75 // Forward Delete
        case 0x4D: 0x77 // End
        case 0x4E: 0x79 // Page Down
        case 0x4F: 0x7C // Right
        case 0x50: 0x7B // Left
        case 0x51: 0x7D // Down
        case 0x52: 0x7E // Up
        case 0x53: 0x47 // Keypad Clear
        case 0x54: 0x4B // Keypad Divide
        case 0x55: 0x43 // Keypad Multiply
        case 0x56: 0x4E // Keypad Minus
        case 0x57: 0x45 // Keypad Plus
        case 0x58: 0x4C // Keypad Enter
        case 0x59...0x62: keypadDigits[Int(usage - 0x59)]
        case 0x63: 0x41 // Keypad Decimal
        case 0x64: 0x0A // ISO extra key beside left Shift
        case 0x65: 0x6E // Contextual menu
        case 0x67: 0x51 // Keypad Equal
        case 0x68...0x6F: functions[Int(usage - 0x68) + 12]
        case 0x85: 0x5F // JIS Keypad Comma
        case 0x87: 0x5E // JIS Underscore
        case 0x89: 0x5D // JIS Yen
        case 0x90: 0x68 // JIS Kana
        case 0x91: 0x66 // JIS Eisu
        case 0xE0...0xE7: modifiers[Int(usage - 0xE0)]
        default: nil
        }
    }
}
